using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioVertexClickValidation
{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static StudioModelEditor editor;static StudioModelDocument doc;static MashBoxStudioViewport view;static bool pending;static int checks,index;static string stage;static StudioModelEditor.ComponentMode kind;static Vector2 markerScreen;
 static object Call(string name,params object[] args)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length&&m.GetParameters().Select((p,i)=>args[i]==null||p.ParameterType.IsInstanceOfType(args[i])).All(v=>v)).Invoke(editor,args);
 static object Get(string name)=>typeof(StudioModelEditor).GetField(name,F).GetValue(editor);static void Set(string name,object value)=>typeof(StudioModelEditor).GetField(name,F).SetValue(editor,value);
 static void Check(bool value,string message){if(!value)throw new Exception(stage+": "+message);checks++;}
 static void Target(int node,StudioModelEditor.ComponentMode mode,params int[] selected){Call("ActivateComponentTarget",node,mode);editor.Components.Clear();editor.Components.UnionWith(selected);}
 static void History(bool redo=false){UnityEditor.Undo.FlushUndoRecordObjects();StudioUndo.IncrementCurrentGroup();if(redo)StudioUndo.PerformRedo();else StudioUndo.PerformUndo();}
 static void Reset(){UnityEditor.Undo.ClearAll();StudioUndo.ClearForTests();StudioUndo.IncrementCurrentGroup();}
 public static void Run(){EditorApplication.delayCall+=()=>{try{doc=ScriptableObject.CreateInstance<StudioModelDocument>();for(int i=0;i<2;i++){var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var p);doc.nodes.Add(new StudioModelDocument.Node{name="Target "+i,mesh=mesh,cutPolygons=p,cutTriangles=mesh.triangles,position=Vector3.right*(i==0?-1.2f:1.2f)});}editor=new StudioModelEditor(()=>{});editor.Load(doc);view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.position=new Rect(80,80,900,650);view.Bind(editor.Scene);view.Show();view.LookAtDirect(Vector3.zero,Quaternion.Euler(10,15,0),4);SceneView.duringSceneGui+=Draw;pending=true;view.Repaint();}catch(Exception ex){Finish(ex);}};}
 static void Draw(SceneView scene)
 {
  if(scene!=view||!pending||Event.current.type!=EventType.Repaint)return;pending=false;
  try
  {
   if(index<3)
   {
    kind=(StudioModelEditor.ComponentMode)(index+1);stage=kind+" replacement";Target(0,kind,0);Target(1,kind,0);Set("end",HandleUtility.WorldToGUIPoint(editor.Transforms[0].position));Set("additive",true);Set("subtract",false);Call("PickCore",view,new Rect(),true);Check(editor.ToolbarComponentMode==kind&&editor.Active==0&&((HashSet<int>)Get("objects")).SetEquals(new[]{0,1}),"Modified component click lost multi-editing");Target(0,kind,0);Target(1,kind,0);Set("additive",false);Reset();Call("Pick",view,new Rect(),true);Check(editor.ToolbarComponentMode==StudioModelEditor.ComponentMode.Object&&editor.Active==0,"Different-object click did not enter Object mode");Check(((HashSet<int>)Get("objects")).SetEquals(new[]{0})&&editor.Components.Count==0,"Click did not replace selection");Check(StudioUndo.RetainedActions==1,"Click recorded extra history");EditorApplication.delayCall+=ValidateHistory;return;
   }
   stage="purple marker renders";Target(0,StudioModelEditor.ComponentMode.Vertex);Target(1,StudioModelEditor.ComponentMode.Vertex);Set("displayXray",true);editor.ForceLegacyVertexMarkers=false;Call("ClearAllComponentDrawCaches");var gpu=Render("vertex-purple.png");Check(gpu.Count(Purple)>120,"Purple markers missing");Check(PurpleWidth(gpu)>=Mathf.RoundToInt(5*EditorGUIUtility.pixelsPerPoint)-1,"Vertex markers were not enlarged");long uploads=editor.VertexMarkerUploadBytes;Render(null);Check(editor.VertexMarkerUploadBytes==uploads,"Unchanged redraw uploaded geometry");editor.ForceLegacyVertexMarkers=true;Call("ClearAllComponentDrawCaches");var legacy=Render(null);Check(gpu.SequenceEqual(legacy),"GPU/fallback purple marker style differs");editor.ForceLegacyVertexMarkers=false;Call("ClearAllComponentDrawCaches");editor.Components.Add(0);var selected=Render("vertex-purple-selected.png");Check(selected.Any(c=>c.r>180&&c.r>c.g+20&&c.g>c.b+35),"Selected vertices lost orange distinction");Check(selected.Any(Purple),"Selected overlay removed purple unselected markers");Finish(null);
  }catch(Exception ex){Finish(ex);}
 }
 static void ValidateHistory(){try{History();Check(editor.Active==1&&editor.ToolbarComponentMode==kind&&((HashSet<int>)Get("objects")).SetEquals(new[]{0,1}),"Undo did not restore component cohort");Check(editor.Components.SetEquals(new[]{0}),"Undo lost active components");History(true);Check(editor.Active==0&&editor.ToolbarComponentMode==StudioModelEditor.ComponentMode.Object&&((HashSet<int>)Get("objects")).SetEquals(new[]{0}),"Redo did not restore exclusive object selection");History();index++;pending=true;view.Repaint();}catch(Exception ex){Finish(ex);}}
 static bool Purple(Color32 color)=>color.a>100&&color.b>color.g+30&&color.r>color.g+20;
 static int PurpleWidth(Color32[] pixels){var x=(int)markerScreen.x;var y=(int)markerScreen.y;int left=512,right=-1;for(int row=Mathf.Max(0,y-12);row<Mathf.Min(320,y+13);row++)for(int col=Mathf.Max(0,x-12);col<Mathf.Min(512,x+13);col++)if(Purple(pixels[row*512+col])){left=Math.Min(left,col);right=Math.Max(right,col);}return right-left+1;}
 static Color32[] Render(string file)
 {
  var camera=view.camera;var rt=new RenderTexture(512,320,24);rt.Create();var oldTarget=camera.targetTexture;var rect=camera.pixelRect;var position=camera.transform.position;var rotation=camera.transform.rotation;bool ortho=camera.orthographic;float size=camera.orthographicSize;var projection=camera.projectionMatrix;var world=camera.worldToCameraMatrix;var active=RenderTexture.active;GL.PushMatrix();
  try{camera.targetTexture=rt;camera.pixelRect=new Rect(0,0,512,320);camera.transform.SetPositionAndRotation(new Vector3(0,0,-5),Quaternion.identity);camera.orthographic=true;camera.orthographicSize=1.5f;camera.ResetProjectionMatrix();camera.ResetWorldToCameraMatrix();markerScreen=camera.WorldToScreenPoint(editor.Transforms[0].TransformPoint(doc.nodes[0].mesh.vertices[0]));Handles.SetCamera(new Rect(0,0,512,320),camera);RenderTexture.active=rt;GL.Clear(true,true,new Color(.2f,.2f,.2f,1));GL.LoadProjectionMatrix(camera.projectionMatrix);GL.modelview=camera.worldToCameraMatrix;Call("DrawComponents",view);var image=new Texture2D(512,320,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,512,320),0,0);image.Apply();var pixels=image.GetPixels32();if(file!=null)File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+file)),image.EncodeToPNG());Object.DestroyImmediate(image);return pixels;}finally{GL.PopMatrix();camera.targetTexture=oldTarget;camera.pixelRect=rect;camera.transform.SetPositionAndRotation(position,rotation);camera.orthographic=ortho;camera.orthographicSize=size;camera.projectionMatrix=projection;camera.worldToCameraMatrix=world;RenderTexture.active=active;Object.DestroyImmediate(rt);}
 }
 static void Finish(Exception ex){SceneView.duringSceneGui-=Draw;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../vertex-click-result.txt")),ex==null?"PASS "+checks+" V/E/F click replacement, history, purple marker size/render/parity/cache checks":stage+"\n"+ex);EditorApplication.delayCall+=()=>{if(view)view.Close();editor?.Dispose();if(doc){foreach(var node in doc.nodes)if(node.mesh)Object.DestroyImmediate(node.mesh);Object.DestroyImmediate(doc);}double exitAt=EditorApplication.timeSinceStartup+1;void Exit(){if(EditorApplication.timeSinceStartup<exitAt)return;EditorApplication.update-=Exit;EditorApplication.Exit(ex==null?0:1);}EditorApplication.update+=Exit;};}
}
